SET NAMES utf8mb4;

DROP TABLE IF EXISTS `community_fee_bill`;
CREATE TABLE `community_fee_bill` (
  `bill_id` bigint NOT NULL COMMENT '账单ID',
  `bill_no` varchar(64) DEFAULT NULL COMMENT '账单编号',
  `owner_id` bigint DEFAULT NULL COMMENT '业主ID',
  `owner_name` varchar(50) DEFAULT NULL COMMENT '业主姓名',
  `room_id` bigint DEFAULT NULL COMMENT '房屋ID',
  `item_id` bigint DEFAULT NULL COMMENT '费用项目ID',
  `item_name` varchar(100) DEFAULT NULL COMMENT '费用项目名称',
  `bill_year` int DEFAULT NULL COMMENT '账单年份',
  `bill_month` int DEFAULT NULL COMMENT '账单月份',
  `receivable_amount` decimal(10,2) DEFAULT NULL COMMENT '应收金额',
  `received_amount` decimal(10,2) DEFAULT '0.00' COMMENT '已收金额',
  `unpaid_amount` decimal(10,2) DEFAULT NULL COMMENT '未收金额',
  `due_date` date DEFAULT NULL COMMENT '缴费截止日期',
  `bill_status` char(1) DEFAULT '0' COMMENT '账单状态（0未缴 1部分缴费 2已缴 3作废）',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`bill_id`),
  KEY `idx_fee_bill_owner_id` (`owner_id`),
  KEY `idx_fee_bill_room_id` (`room_id`),
  KEY `idx_fee_bill_item_id` (`item_id`),
  KEY `idx_fee_bill_no` (`bill_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='费用账单表';

DROP TEMPORARY TABLE IF EXISTS `tmp_bill_ref`;
CREATE TEMPORARY TABLE `tmp_bill_ref` AS
SELECT (@rownum := @rownum + 1) AS rn, t.*
FROM (
  SELECT DISTINCT o.owner_id, o.owner_real_name, r.room_id, r.room_acreage
  FROM `owner_room` od
  INNER JOIN `owner` o ON o.owner_id = od.owner_id
  INNER JOIN `room` r ON r.room_id = od.room_id
  ORDER BY od.owner_room_id
  LIMIT 4
) t, (SELECT @rownum := 0) x;

